package com.shadowbooks.data

import androidx.compose.ui.graphics.Color
import com.shadowbooks.audio.LabSoundType

object PeriodicTableData {
    val elements: List<ChemicalElement> by lazy {
        elementsPart1() + elementsPart2() + elementsPart3() + elementsPart4()
    }

    private fun el(
        z: Int,
        symbol: String,
        arabic: String,
        english: String,
        massNum: Int,
        atomicMass: String,
        config: String,
        fullConfig: String,
        shells: List<Int>,
        category: ElementCategory,
        row: Int,
        col: Int,
        state: MatterState,
        style: ElementVisualStyle,
        color1: Long,
        color2: Long,
        appearance: String,
        summary: String,
        reactions: List<ElementReaction>,
    ) = ChemicalElement(
        atomicNumber = z,
        symbol = symbol,
        arabicName = arabic,
        englishName = english,
        massNumber = massNum,
        atomicMass = atomicMass,
        electronConfig = config,
        fullElectronConfig = fullConfig,
        shells = shells,
        category = category,
        gridRow = row,
        gridCol = col,
        state = state,
        visualStyle = style,
        sampleColor = Color(color1),
        sampleSecondaryColor = Color(color2),
        appearanceArabic = appearance,
        summaryArabic = summary,
        reactions = reactions,
    )

    private fun rx(
        title: String,
        eq: String,
        effect: String,
        sound: LabSoundType,
        color: Long,
    ) = ElementReaction(title, eq, effect, sound, Color(color))

